<script setup>
// Perfil editable del emprendimiento: datos, redes, formas de pago y seguridad de la cuenta.
import { ref, computed, onMounted, onBeforeUnmount } from "vue";
import { useRouter } from "vue-router";
import { supabase } from "../../lib/supabaseClient";
import { uploadEntrepreneurLogo, deleteImage, getStoragePathFromPublicUrl } from "../../lib/storage";
import BusinessNav from "../../components/business/BusinessNav.vue";
import SubscriptionCard from "../../components/shared/SubscriptionCard.vue";
import DemoSubscriptionModal from "../../components/shared/DemoSubscriptionModal.vue";
import BrandLogo from "../../components/shared/BrandLogo.vue";
import { subscriptionIsActive, activateDemoSubscription } from "../../lib/subscription";
const router=useRouter();const entrepreneur=ref(null);const loading=ref(true),loadError=ref(""),saving=ref(false),logoutLoading=ref(false),paymentLoading=ref(false),deleteLoading=ref(false);const showEditor=ref(false),showPayment=ref(false),showDeleteAccount=ref(false);const deletePassword=ref("");const logoFile=ref(null),logoPreview=ref("");
const form=ref({businessName:"",phone:"",description:"",department:"",district:"",instagramUrl:"",facebookUrl:"",tiktokUrl:"",websiteUrl:"",paymentMethods:[],serviceTags:[]});
const currentPassword=ref(""),newPassword=ref(""),confirmPassword=ref("");const departments=["Ahuachapán","Cabañas","Chalatenango","Cuscatlán","La Libertad","La Paz","La Unión","Morazán","San Miguel","San Salvador","San Vicente","Santa Ana","Sonsonate","Usulután"];
const paymentOptions=["Efectivo","Tarjeta","Transferencia"];
const serviceOptions=["Retiro en local","Entrega a domicilio","Envíos nacionales","Pedidos personalizados","Reserva previa"];
const initials=computed(()=>String(entrepreneur.value?.businessName||"Thrive").trim().split(/\s+/).slice(0,2).map(w=>w[0]?.toUpperCase()).join(""));
// Lo que el emprendedor ya configuró también se muestra en su tarjeta principal.
const profileTags=computed(()=>[...(entrepreneur.value?.paymentMethods||[]),...(entrepreneur.value?.serviceTags||[])]);
const profileSocials=computed(()=>[
    {label:"Instagram",value:entrepreneur.value?.instagramUrl,type:"instagram",class:"bg-pink-50 text-pink-700"},
    {label:"Facebook",value:entrepreneur.value?.facebookUrl,type:"facebook",class:"bg-blue-50 text-blue-700"},
    {label:"TikTok",value:entrepreneur.value?.tiktokUrl,type:"tiktok",class:"bg-gray-100 text-gray-700"},
    {label:"Sitio web",value:entrepreneur.value?.websiteUrl,type:"website",class:"bg-cyan-50 text-[#0077B6]"}
].filter(item=>item.value));
function tagClass(tag){const value=String(tag||"").toLowerCase();if(value.includes("efectivo"))return"bg-emerald-50 text-emerald-700";if(value.includes("tarjeta"))return"bg-indigo-50 text-indigo-700";if(value.includes("transfer"))return"bg-sky-50 text-sky-700";if(value.includes("retiro"))return"bg-amber-50 text-amber-700";if(value.includes("entrega"))return"bg-orange-50 text-orange-700";if(value.includes("envío"))return"bg-violet-50 text-violet-700";if(value.includes("personal"))return"bg-pink-50 text-pink-700";return"bg-[#EAF9FC] text-[#0077B6]";}
function socialHref(item){const value=String(item.value||"").trim();if(/^https?:\/\//i.test(value))return value;const clean=value.replace(/^@/,"");if(item.type==="instagram")return`https://instagram.com/${clean}`;if(item.type==="facebook")return`https://facebook.com/${clean}`;if(item.type==="tiktok")return`https://tiktok.com/@${clean}`;return`https://${clean}`;}
const subscription=computed(()=>({status:entrepreneur.value?.subscriptionStatus||"inactive",price:Number(entrepreneur.value?.subscriptionPrice)||4.99,startedAt:entrepreneur.value?.subscriptionStartedAt||null,expiresAt:entrepreneur.value?.subscriptionExpiresAt||null}));
const hasActiveSubscription=computed(()=>subscriptionIsActive(subscription.value));
function toggleArray(key,value){if(!hasActiveSubscription.value){alert("Las etiquetas del emprendimiento requieren una suscripción activa a Thrive.");return;}const arr=form.value[key];form.value[key]=arr.includes(value)?arr.filter(x=>x!==value):[...arr,value];}
function clearPasswords(){currentPassword.value="";newPassword.value="";confirmPassword.value="";}
function openEditor(){form.value={businessName:entrepreneur.value.businessName,phone:entrepreneur.value.phone,description:entrepreneur.value.description,department:entrepreneur.value.department,district:entrepreneur.value.district,instagramUrl:entrepreneur.value.instagramUrl,facebookUrl:entrepreneur.value.facebookUrl,tiktokUrl:entrepreneur.value.tiktokUrl,websiteUrl:entrepreneur.value.websiteUrl,paymentMethods:[...entrepreneur.value.paymentMethods],serviceTags:[...entrepreneur.value.serviceTags]};logoFile.value=null;logoPreview.value=entrepreneur.value.logoUrl;clearPasswords();showEditor.value=true;document.body.style.overflow="hidden";}
function closeEditor(){showEditor.value=false;logoFile.value=null;logoPreview.value="";clearPasswords();document.body.style.overflow="";}
function handleLogo(e){const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith("image/")||f.size>5*1024*1024){alert("Selecciona una imagen válida de hasta 5 MB.");return;}logoFile.value=f;const reader=new FileReader();reader.onload=x=>logoPreview.value=x.target.result;reader.readAsDataURL(f);}
async function load(){loading.value=true;loadError.value="";try{const{data:{user},error:uErr}=await supabase.auth.getUser();if(uErr||!user)return router.replace({name:"Access"});const[{data:b,error:bErr},{data:p,error:pErr}]=await Promise.all([supabase.from("entrepreneurs").select(`id,business_name,description,department,district,logo_url,instagram_url,facebook_url,tiktok_url,website_url,payment_methods,service_tags,subscription_status,subscription_price,subscription_started_at,subscription_expires_at`).eq("id",user.id).single(),supabase.from("profiles").select("phone").eq("id",user.id).single()]);if(bErr)throw bErr;if(pErr)throw pErr;entrepreneur.value={id:b.id,businessName:b.business_name||"Mi emprendimiento",phone:p.phone||"",email:user.email||"",description:b.description||"",department:b.department||"",district:b.district||"",logoUrl:b.logo_url||"",instagramUrl:b.instagram_url||"",facebookUrl:b.facebook_url||"",tiktokUrl:b.tiktok_url||"",websiteUrl:b.website_url||"",paymentMethods:b.payment_methods||[],serviceTags:b.service_tags||[],subscriptionStatus:b.subscription_status||"inactive",subscriptionPrice:Number(b.subscription_price)||4.99,subscriptionStartedAt:b.subscription_started_at||null,subscriptionExpiresAt:b.subscription_expires_at||null};}catch(e){console.error(e);loadError.value="No fue posible cargar tu perfil.";}finally{loading.value=false;}}
async function saveProfile(){if(saving.value||!form.value.businessName.trim())return;saving.value=true;let uploaded=null;try{const{data:{user}}=await supabase.auth.getUser();if(!user)throw new Error("Sesión no válida");const wantsPassword=currentPassword.value||newPassword.value||confirmPassword.value;if(wantsPassword){if(!currentPassword.value||!newPassword.value||!confirmPassword.value)throw new Error("Completa los tres campos de contraseña.");if(newPassword.value.length<8)throw new Error("La nueva contraseña debe tener al menos 8 caracteres.");if(newPassword.value!==confirmPassword.value)throw new Error("Las nuevas contraseñas no coinciden.");const{error}=await supabase.auth.signInWithPassword({email:user.email,password:currentPassword.value});if(error)throw new Error("La contraseña actual es incorrecta.");}const oldPath=getStoragePathFromPublicUrl(entrepreneur.value.logoUrl);let logoUrl=entrepreneur.value.logoUrl||null;if(logoFile.value){uploaded=await uploadEntrepreneurLogo(user.id,logoFile.value);logoUrl=uploaded.publicUrl;}const{error:bErr}=await supabase.from("entrepreneurs").update({business_name:form.value.businessName.trim(),description:form.value.description.trim(),department:form.value.department||null,district:form.value.district.trim()||null,logo_url:logoUrl,instagram_url:form.value.instagramUrl.trim()||null,facebook_url:form.value.facebookUrl.trim()||null,tiktok_url:form.value.tiktokUrl.trim()||null,website_url:form.value.websiteUrl.trim()||null,payment_methods:hasActiveSubscription.value?form.value.paymentMethods:entrepreneur.value.paymentMethods,service_tags:hasActiveSubscription.value?form.value.serviceTags:entrepreneur.value.serviceTags}).eq("id",user.id);if(bErr)throw bErr;
        // El emprendedor no tiene nombre personal en el formulario: full_name se mantiene vacío.
        const{error:pErr}=await supabase.from("profiles").update({full_name:null,phone:form.value.phone.trim(),avatar_url:logoUrl}).eq("id",user.id);if(pErr)throw pErr;
        // También limpiamos metadatos antiguos que pudieran mostrarse como Display name.
        await supabase.auth.updateUser({data:{full_name:null,display_name:null,name:null}});
        if(uploaded?.path&&oldPath&&oldPath!==uploaded.path){try{await deleteImage(oldPath);}catch{}}
        if(wantsPassword){const{error}=await supabase.auth.updateUser({password:newPassword.value});if(error)throw error;}
        entrepreneur.value={...entrepreneur.value,businessName:form.value.businessName.trim(),phone:form.value.phone.trim(),description:form.value.description.trim(),department:form.value.department,district:form.value.district.trim(),logoUrl:logoUrl||"",instagramUrl:form.value.instagramUrl.trim(),facebookUrl:form.value.facebookUrl.trim(),tiktokUrl:form.value.tiktokUrl.trim(),websiteUrl:form.value.websiteUrl.trim(),paymentMethods:hasActiveSubscription.value?[...form.value.paymentMethods]:[...entrepreneur.value.paymentMethods],serviceTags:hasActiveSubscription.value?[...form.value.serviceTags]:[...entrepreneur.value.serviceTags]};closeEditor();alert("Perfil actualizado correctamente.");
    }catch(e){console.error(e);if(uploaded?.path){try{await deleteImage(uploaded.path);}catch{}}alert(e.message||"No fue posible guardar los cambios.");}finally{saving.value=false;}}
function openPayment(){showPayment.value=true;document.body.style.overflow="hidden";}function closePayment(){if(paymentLoading.value)return;showPayment.value=false;document.body.style.overflow="";}async function confirmDemoPayment(){paymentLoading.value=true;try{const result=await activateDemoSubscription();entrepreneur.value={...entrepreneur.value,subscriptionStatus:result.status,subscriptionPrice:result.price,subscriptionStartedAt:result.startedAt,subscriptionExpiresAt:result.expiresAt};closePayment();}catch(e){alert(e.message||"No fue posible activar el plan.");}finally{paymentLoading.value=false;}}
async function logout(){logoutLoading.value=true;try{await supabase.auth.signOut({scope:"local"});router.replace({name:"Access"});}finally{logoutLoading.value=false;}}
// Borrar cuenta exige volver a comprobar la contraseña antes de eliminar los datos.
function openDeleteAccount(){deletePassword.value="";showDeleteAccount.value=true;document.body.style.overflow="hidden";}
function closeDeleteAccount(){if(deleteLoading.value)return;showDeleteAccount.value=false;deletePassword.value="";document.body.style.overflow="";}
async function deleteAccount(){
    if(deleteLoading.value)return;
    if(!deletePassword.value){alert("Escribe tu contraseña para continuar.");return;}
    deleteLoading.value=true;
    try{
        const{data:{user},error:userError}=await supabase.auth.getUser();
        if(userError||!user?.email)throw new Error("No pudimos comprobar tu sesión.");
        const{error:passwordError}=await supabase.auth.signInWithPassword({email:user.email,password:deletePassword.value});
        if(passwordError)throw new Error("La contraseña es incorrecta.");
        const{data,error}=await supabase.functions.invoke("delete-account",{body:{confirm:true}});
        if(error)throw error;
        if(data?.error)throw new Error(data.error);
        showDeleteAccount.value=false;
        deletePassword.value="";
        try{await supabase.auth.signOut({scope:"local"});}catch{}
        router.replace({name:"Access",query:{deleted:"1"}});
    }catch(error){console.error(error);alert(error.message||"No fue posible borrar la cuenta.");}
    finally{deleteLoading.value=false;}
}
function esc(e){if(e.key!=="Escape")return;if(showEditor.value)closeEditor();else if(showPayment.value)closePayment();else if(showDeleteAccount.value)closeDeleteAccount();}
onMounted(async()=>{await load();document.addEventListener("keydown",esc)});onBeforeUnmount(()=>{document.removeEventListener("keydown",esc);document.body.style.overflow="";});
</script>
<template>
<div class="min-h-screen bg-[#F8FBFC] pb-[78px] text-gray-700 lg:pb-10"><BusinessNav active="profile" :business-name="entrepreneur?.businessName||'Thrive'"/><main v-if="loading" class="py-24 text-center"><div class="mx-auto h-9 w-9 animate-spin rounded-full border-4 border-[#CAF0F8] border-t-[#00B4D8]"></div></main><main v-else-if="loadError" class="mx-auto max-w-xl px-5 py-24 text-center">{{ loadError }}</main><main v-else-if="entrepreneur" class="mx-auto max-w-[1450px] px-3 py-5 sm:px-5 lg:px-8"><section class="rounded-[28px] bg-white p-5 shadow-sm sm:p-7"><div class="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between"><div class="flex flex-col items-center gap-5 text-center sm:flex-row sm:text-left"><BrandLogo :src="entrepreneur.logoUrl" :alt="entrepreneur.businessName" :name="entrepreneur.businessName" size="profile"/><div class="min-w-0"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Perfil del emprendimiento</p><h1 class="mt-1 text-2xl font-black sm:text-3xl">{{ entrepreneur.businessName }}</h1><p class="mt-1 text-sm text-gray-400">{{ entrepreneur.email }}</p><p class="mt-1 text-sm text-gray-400">{{ entrepreneur.phone||'Teléfono no registrado' }}</p><div v-if="profileTags.length" class="mt-3 flex flex-wrap justify-center gap-1.5 sm:justify-start"><span v-for="tag in profileTags" :key="tag" class="rounded-full px-2.5 py-1 text-[10px] font-bold" :class="tagClass(tag)">{{ tag }}</span></div><div v-if="profileSocials.length" class="mt-2 flex flex-wrap justify-center gap-1.5 sm:justify-start"><a v-for="social in profileSocials" :key="social.label" :href="socialHref(social)" target="_blank" rel="noopener noreferrer" class="rounded-full px-2.5 py-1 text-[10px] font-bold" :class="social.class">{{ social.label }}</a></div></div></div><div class="flex flex-col gap-2 sm:flex-row"><button class="rounded-[15px] border border-[#00B4D8] px-5 py-3 text-sm font-black text-[#0077B6]" @click="openEditor">Editar perfil</button><button :disabled="logoutLoading" class="hidden rounded-[15px] bg-red-50 px-5 py-3 text-sm font-black text-red-600 lg:block" @click="logout">Cerrar sesión</button></div></div></section><SubscriptionCard class="mt-5" :subscription="subscription" :loading="paymentLoading" @subscribe="openPayment"/><section class="mt-5 grid gap-4 lg:grid-cols-2"><article class="rounded-[26px] bg-white p-5 shadow-sm"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Presentación</p><p class="mt-3 whitespace-pre-line text-sm leading-7 text-gray-500">{{ entrepreneur.description||'Agrega una descripción para presentar tu emprendimiento.' }}</p><div class="mt-4 flex flex-wrap gap-2"><span v-for="tag in [...entrepreneur.paymentMethods,...entrepreneur.serviceTags]" :key="tag" class="rounded-full bg-[#EAF9FC] px-3 py-1.5 text-xs font-bold text-[#0077B6]">{{ tag }}</span></div></article><article class="rounded-[26px] bg-white p-5 shadow-sm"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Presencia digital</p><div class="mt-3 space-y-2 text-sm text-gray-500"><p><b class="text-gray-600">Instagram:</b> {{ entrepreneur.instagramUrl||'No registrado' }}</p><p><b class="text-gray-600">Facebook:</b> {{ entrepreneur.facebookUrl||'No registrado' }}</p><p><b class="text-gray-600">TikTok:</b> {{ entrepreneur.tiktokUrl||'No registrado' }}</p><p><b class="text-gray-600">Sitio web:</b> {{ entrepreneur.websiteUrl||'No registrado' }}</p></div></article></section>
<section class="mt-8 rounded-[24px] border border-red-100 bg-white p-5 shadow-sm sm:flex sm:items-center sm:justify-between sm:gap-5">
    <div><p class="text-xs font-black uppercase tracking-[.14em] text-red-500">Cuenta</p><h2 class="mt-1 text-lg font-black text-gray-700">Borrar cuenta</h2><p class="mt-1 max-w-2xl text-sm leading-6 text-gray-400">Elimina definitivamente tu emprendimiento, productos, locales, reseñas relacionadas, pedidos, imágenes y acceso a Thrive.</p></div>
    <button type="button" class="mt-4 w-full rounded-[14px] border border-red-200 bg-red-50 px-5 py-3 text-sm font-black text-red-600 transition hover:bg-red-100 sm:mt-0 sm:w-auto sm:shrink-0" @click="openDeleteAccount">Borrar cuenta</button>
</section></main>
<Teleport to="body"><div v-if="showEditor" class="fixed inset-0 z-[130] flex items-end justify-center bg-black/50 sm:items-center sm:p-5" @click.self="closeEditor"><section class="max-h-[94vh] w-full overflow-y-auto rounded-t-[28px] bg-white sm:max-w-[760px] sm:rounded-[28px]"><div class="sticky top-0 z-10 flex items-center justify-between border-b bg-white px-5 py-4"><div><p class="text-xs font-black uppercase tracking-[.14em] text-[#00B4D8]">Tu negocio</p><h2 class="text-xl font-black">Editar perfil</h2></div><button class="h-9 w-9 rounded-full bg-gray-100" @click="closeEditor">×</button></div><form class="space-y-5 p-5 sm:p-6" @submit.prevent="saveProfile"><div class="flex items-center gap-4"><BrandLogo :src="logoPreview" :alt="form.businessName||entrepreneur.businessName" :name="form.businessName||entrepreneur.businessName" size="lg"/><label class="cursor-pointer rounded-xl bg-[#EAF9FC] px-4 py-2 text-sm font-black text-[#0077B6]">Cambiar logo<input type="file" accept="image/*" class="hidden" @change="handleLogo"></label></div><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">Nombre del emprendimiento<input v-model="form.businessName" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none focus:border-[#00B4D8]"></label><label class="text-sm font-bold">WhatsApp / teléfono<input v-model="form.phone" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none focus:border-[#00B4D8]"></label><label class="text-sm font-bold">Departamento<select v-model="form.department" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none"><option value="">Selecciona</option><option v-for="d in departments" :key="d">{{ d }}</option></select></label><label class="text-sm font-bold">Distrito<input v-model="form.district" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none"></label></div><label class="block text-sm font-bold">Descripción<textarea v-model="form.description" rows="4" class="mt-1 w-full rounded-xl border border-gray-200 p-4 outline-none focus:border-[#00B4D8]"></textarea></label><div><p class="text-sm font-black">Redes sociales</p><div class="mt-2 grid gap-3 sm:grid-cols-2"><input v-model="form.instagramUrl" placeholder="Instagram: usuario o URL" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"><input v-model="form.facebookUrl" placeholder="Facebook: usuario o URL" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"><input v-model="form.tiktokUrl" placeholder="TikTok: usuario o URL" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"><input v-model="form.websiteUrl" placeholder="Sitio web" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"></div></div><div><p class="text-sm font-black">Formas de pago</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="x in paymentOptions" :key="x" type="button" class="rounded-full px-3 py-2 text-xs font-bold" :class="form.paymentMethods.includes(x)?'bg-[#00B4D8] text-white':'bg-gray-100 text-gray-500'" @click="toggleArray('paymentMethods',x)">{{ x }}</button></div></div><div><p class="text-sm font-black">Servicios y condiciones</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="x in serviceOptions" :key="x" type="button" class="rounded-full px-3 py-2 text-xs font-bold" :class="form.serviceTags.includes(x)?'bg-[#00B4D8] text-white':'bg-gray-100 text-gray-500'" @click="toggleArray('serviceTags',x)">{{ x }}</button></div></div><div class="rounded-[18px] bg-[#F8FBFC] p-4"><p class="text-sm font-black">Cambiar contraseña <span class="font-normal text-gray-400">(opcional)</span></p><div class="mt-3 grid gap-2"><input v-model="currentPassword" type="password" placeholder="Contraseña actual" class="rounded-xl border border-gray-200 px-4 py-3"><input v-model="newPassword" type="password" placeholder="Nueva contraseña" class="rounded-xl border border-gray-200 px-4 py-3"><input v-model="confirmPassword" type="password" placeholder="Confirmar nueva contraseña" class="rounded-xl border border-gray-200 px-4 py-3"></div></div><button :disabled="saving" class="w-full rounded-[15px] bg-[#00B4D8] px-5 py-3.5 font-black text-white disabled:opacity-50">{{ saving?'Guardando...':'Guardar cambios' }}</button></form></section></div></Teleport>
<Teleport to="body">
<div v-if="showDeleteAccount" class="fixed inset-0 z-[170] flex items-end justify-center bg-black/55 sm:items-center sm:p-5" @click.self="closeDeleteAccount">
    <section class="w-full rounded-t-[28px] bg-white p-5 sm:max-w-[470px] sm:rounded-[28px] sm:p-6">
        <div class="flex items-start justify-between gap-4"><div><p class="text-xs font-black uppercase tracking-[.14em] text-red-500">Acción permanente</p><h2 class="mt-1 text-xl font-black text-gray-800">Borrar tu cuenta</h2></div><button type="button" class="flex h-9 w-9 items-center justify-center rounded-full bg-gray-100 font-bold text-gray-500" @click="closeDeleteAccount">×</button></div>
        <p class="mt-4 text-sm leading-6 text-gray-500">Esta acción no se puede deshacer. Para confirmar que eres tú, escribe la contraseña de tu cuenta.</p>
        <label class="mt-5 block text-sm font-bold text-gray-700">Contraseña<input v-model="deletePassword" type="password" autocomplete="current-password" placeholder="Tu contraseña" class="mt-2 w-full rounded-[14px] border border-gray-200 px-4 py-3 outline-none transition focus:border-red-300" @keyup.enter="deleteAccount"></label>
        <div class="mt-5 grid grid-cols-2 gap-2"><button type="button" :disabled="deleteLoading" class="rounded-[14px] border border-gray-200 px-4 py-3 text-sm font-black text-gray-500 disabled:opacity-50" @click="closeDeleteAccount">Cancelar</button><button type="button" :disabled="deleteLoading||!deletePassword" class="rounded-[14px] bg-red-600 px-4 py-3 text-sm font-black text-white disabled:opacity-45" @click="deleteAccount">{{ deleteLoading?'Borrando...':'Borrar definitivamente' }}</button></div>
    </section>
</div>
</Teleport>
<DemoSubscriptionModal :show="showPayment" :loading="paymentLoading" :price="subscription.price" @close="closePayment" @confirm="confirmDemoPayment"/>
</div>
</template>
